{"ideviceId":"idevice-1793835226401-bd0i10gbz","textInfoDurationInput":"","textInfoDurationTextInput":"Duración","textInfoParticipantsInput":"","textInfoParticipantsTextInput":"Agrupamiento","textTextarea":"<div id="juego-arboles-binarios" style="font-family: Arial, Helvetica, sans-serif; color: #1f2937; line-height: 1.65; max-width: 1100px; margin: 0 auto;"><!-- ENCABEZADO -->
<div style="background: #3B82F6; color: #ffffff; padding: 26px 30px; border-radius: 10px; margin-bottom: 24px;">
<div style="display: inline-block; background: #FBBF24; color: #1f2937; padding: 5px 12px; border-radius: 20px; font-size: 14px; font-weight: bold; margin-bottom: 12px;">Actividad interactiva</div>
<h2 style="margin: 0 0 10px; color: #ffffff; font-size: 28px;">Juego de relacionar: Árboles binarios</h2>
<p style="margin: 0; color: #ffffff; font-size: 16px;">Relaciona los conceptos con sus definiciones correctas y comprueba tus conocimientos sobre árboles binarios.</p>
</div>
<!-- INSTRUCCIONES -->
<div style="background: #F9F9FB; border: 1px solid #E5E7EB; border-left: 6px solid #10B981; padding: 20px 24px; border-radius: 8px; margin-bottom: 22px;">
<h3 style="margin: 0 0 10px; font-size: 21px; color: #1f2937;">Indicaciones</h3>
<p style="margin: 0 0 12px;">Lee cada concepto y selecciona la definición que consideres correcta. Cuando completes las diez relaciones, presiona <strong>Comprobar respuestas</strong> para conocer tu puntuación.</p>
<ul style="margin: 0; padding-left: 23px;">
<li>Cada respuesta correcta equivale a <strong>1 punto</strong>.</li>
<li>La puntuación máxima es de <strong>10 puntos</strong>.</li>
<li>Dispones de <strong>intentos ilimitados</strong>.</li>
<li>Las definiciones cambian de orden en cada nuevo intento.</li>
</ul>
</div>
<!-- MARCADORES -->
<div style="display: flex; flex-wrap: wrap; gap: 14px; margin-bottom: 22px;">
<div style="flex: 1 1 150px; background: #EFF6FF; border: 1px solid #BFDBFE; padding: 16px; border-radius: 9px; text-align: center;">
<div style="font-size: 13px; color: #1d4ed8; font-weight: bold;">PUNTUACIÓN</div>
<div id="ab-puntuacion" style="font-size: 30px; font-weight: bold; color: #1d4ed8;" aria-live="polite">0 / 10</div>
</div>
<div style="flex: 1 1 150px; background: #ECFDF5; border: 1px solid #A7F3D0; padding: 16px; border-radius: 9px; text-align: center;">
<div style="font-size: 13px; color: #047857; font-weight: bold;">RESPONDIDAS</div>
<div id="ab-respondidas" style="font-size: 30px; font-weight: bold; color: #047857;">0 / 10</div>
</div>
<div style="flex: 1 1 150px; background: #FFFBEB; border: 1px solid #FDE68A; padding: 16px; border-radius: 9px; text-align: center;">
<div style="font-size: 13px; color: #92400e; font-weight: bold;">INTENTO</div>
<div id="ab-intento" style="font-size: 30px; font-weight: bold; color: #92400e;">1</div>
</div>
</div>
<!-- BARRA DE PROGRESO -->
<div style="margin-bottom: 24px;">
<div style="display: flex; justify-content: space-between; font-size: 14px; margin-bottom: 7px;"><strong>Progreso de la actividad</strong> <span id="ab-progreso-texto">0%</span></div>
<div style="height: 12px; background: #E5E7EB; border-radius: 20px; overflow: hidden;">
<div id="ab-progreso-barra" style="height: 100%; width: 0%; background: #10B981; border-radius: 20px; transition: width 0.25s ease;"></div>
</div>
</div>
<!-- ÁREA DEL JUEGO -->
<section style="margin-bottom: 25px;">
<h3 style="color: #1f2937; font-size: 22px; border-bottom: 3px solid #3B82F6; padding-bottom: 9px; margin-bottom: 18px;">Relaciona cada concepto</h3>
<div id="ab-preguntas"></div>
</section>
<!-- BOTONES -->
<div style="display: flex; flex-wrap: wrap; gap: 12px; margin: 22px 0;"><button id="ab-comprobar" type="button" style="flex: 1 1 220px; background: #3B82F6; color: #ffffff; border: none; border-radius: 8px; padding: 15px 20px; font-size: 16px; font-weight: bold; cursor: pointer;"> Comprobar respuestas </button> <button id="ab-reiniciar" type="button" style="flex: 1 1 220px; background: #1F2937; color: #ffffff; border: none; border-radius: 8px; padding: 15px 20px; font-size: 16px; font-weight: bold; cursor: pointer;"> Nuevo intento </button></div>
<!-- RESULTADO -->
<div id="ab-resultado" role="status" aria-live="polite" style="display: none; background: #F9F9FB; border: 1px solid #E5E7EB; border-radius: 10px; padding: 24px; margin-top: 20px; text-align: center;">
<h3 id="ab-resultado-titulo" style="margin: 0 0 10px; color: #1f2937; font-size: 23px;"></h3>
<div id="ab-resultado-nota" style="font-size: 38px; font-weight: bold; color: #3b82f6; margin-bottom: 10px;"></div>
<p id="ab-resultado-mensaje" style="margin: 0; font-size: 16px;"></p>
</div>
<!-- MENSAJE FINAL -->
<div style="background: #1F2937; color: #ffffff; padding: 22px 26px; border-radius: 9px; margin-top: 28px;">
<h3 style="margin: 0 0 10px; color: #fbbf24; font-size: 20px;">Sobre la actividad</h3>
<p style="margin: 0;">Esta actividad integra conceptos de los cinco subtemas: fundamentos, tipos de árboles binarios, operaciones fundamentales, recorridos e implementación en Python.</p>
</div>
</div>
<p>
<script>
(function () {
    "use strict";

    const contenedor = document.getElementById(
        "juego-arboles-binarios"
    );

    if (!contenedor || contenedor.dataset.iniciado === "true") {
        return;
    }

    contenedor.dataset.iniciado = "true";

    const elementos = [
        {
            id: 1,
            concepto: "Árbol binario",
            definicion: "Estructura de datos no lineal en la que cada nodo puede tener como máximo dos hijos."
        },
        {
            id: 2,
            concepto: "Nodo raíz",
            definicion: "Nodo principal del árbol que no posee padre y desde el cual se originan las demás conexiones."
        },
        {
            id: 3,
            concepto: "Árbol binario lleno",
            definicion: "Árbol en el que cada nodo tiene exactamente cero o dos hijos."
        },
        {
            id: 4,
            concepto: "Árbol binario completo",
            definicion: "Árbol cuyos niveles, excepto posiblemente el último, están llenos y cuyo último nivel se ocupa de izquierda a derecha."
        },
        {
            id: 5,
            concepto: "Inserción en un BST",
            definicion: "Operación que incorpora un nodo ubicando los valores menores a la izquierda y los mayores a la derecha."
        },
        {
            id: 6,
            concepto: "Eliminación de un nodo con dos hijos",
            definicion: "Operación que puede reemplazar el valor eliminado por su sucesor inorden para conservar la organización del BST."
        },
        {
            id: 7,
            concepto: "Recorrido en preorden",
            definicion: "Recorrido que visita primero la raíz, después el subárbol izquierdo y finalmente el derecho."
        },
        {
            id: 8,
            concepto: "Recorrido en inorden",
            definicion: "Recorrido que visita el subárbol izquierdo, luego la raíz y finalmente el derecho."
        },
        {
            id: 9,
            concepto: "Clase Node en Python",
            definicion: "Clase que representa un nodo mediante un valor y dos referencias hacia sus posibles hijos."
        },
        {
            id: 10,
            concepto: "Método search() en un BST",
            definicion: "Método que localiza un valor mediante comparaciones sucesivas y devuelve True o False."
        }
    ];

    const preguntas = contenedor.querySelector("#ab-preguntas");
    const puntuacion = contenedor.querySelector("#ab-puntuacion");
    const respondidas = contenedor.querySelector("#ab-respondidas");
    const intentoTexto = contenedor.querySelector("#ab-intento");
    const progresoTexto = contenedor.querySelector("#ab-progreso-texto");
    const progresoBarra = contenedor.querySelector("#ab-progreso-barra");

    const botonComprobar = contenedor.querySelector("#ab-comprobar");
    const botonReiniciar = contenedor.querySelector("#ab-reiniciar");

    const resultado = contenedor.querySelector("#ab-resultado");
    const resultadoTitulo = contenedor.querySelector("#ab-resultado-titulo");
    const resultadoNota = contenedor.querySelector("#ab-resultado-nota");
    const resultadoMensaje = contenedor.querySelector("#ab-resultado-mensaje");

    let intento = 1;
    let evaluado = false;
    let respuestasAleatorias = [];

    // Mezclar un arreglo sin modificar el original.
    function mezclar(lista) {
        const copia = [...lista];

        for (let i = copia.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [copia[i], copia[j]] = [copia[j], copia[i]];
        }

        return copia;
    }

    // Actualizar progreso.
    function actualizarProgreso() {
        const selects = preguntas.querySelectorAll("select");

        let cantidad = 0;

        selects.forEach(function (select) {
            if (select.value !== "") {
                cantidad++;
            }
        });

        respondidas.textContent = cantidad + " / 10";

        const porcentaje = Math.round(
            (cantidad / elementos.length) * 100
        );

        progresoTexto.textContent = porcentaje + "%";
        progresoBarra.style.width = porcentaje + "%";
    }

    // Crear cada pregunta.
    function crearPregunta(elemento, indice) {
        const tarjeta = document.createElement("div");

        tarjeta.style.cssText =
            "background:#FFFFFF;" +
            "border:1px solid #E5E7EB;" +
            "border-left:5px solid #3B82F6;" +
            "padding:18px 20px;" +
            "border-radius:9px;" +
            "margin-bottom:14px;";

        const encabezado = document.createElement("div");

        encabezado.style.cssText =
            "display:flex;" +
            "flex-wrap:wrap;" +
            "align-items:center;" +
            "gap:12px;" +
            "margin-bottom:13px;";

        const numero = document.createElement("span");

        numero.textContent = indice + 1;

        numero.style.cssText =
            "display:inline-flex;" +
            "align-items:center;" +
            "justify-content:center;" +
            "width:34px;" +
            "height:34px;" +
            "background:#3B82F6;" +
            "color:#FFFFFF;" +
            "border-radius:50%;" +
            "font-weight:bold;" +
            "flex-shrink:0;";

        const concepto = document.createElement("strong");

        concepto.textContent = elemento.concepto;

        concepto.style.cssText =
            "font-size:17px;" +
            "color:#1F2937;";

        encabezado.appendChild(numero);
        encabezado.appendChild(concepto);

        // Etiqueta accesible.
        const etiqueta = document.createElement("label");

        etiqueta.textContent = "Selecciona la definición correcta:";

        etiqueta.style.cssText =
            "display:block;" +
            "font-size:14px;" +
            "color:#475569;" +
            "margin-bottom:8px;";

        const select = document.createElement("select");

        select.id = "ab-select-" + elemento.id;
        select.dataset.correcta = String(elemento.id);

        etiqueta.htmlFor = select.id;

        select.style.cssText =
            "width:100%;" +
            "max-width:100%;" +
            "box-sizing:border-box;" +
            "padding:12px;" +
            "border:1px solid #CBD5E1;" +
            "border-radius:7px;" +
            "background:#FFFFFF;" +
            "color:#1F2937;" +
            "font-family:Arial,Helvetica,sans-serif;" +
            "font-size:14px;" +
            "line-height:1.5;";

        const opcionInicial = document.createElement("option");

        opcionInicial.value = "";
        opcionInicial.textContent = "-- Selecciona una definición --";

        select.appendChild(opcionInicial);

        respuestasAleatorias.forEach(function (respuesta) {
            const opcion = document.createElement("option");

            opcion.value = String(respuesta.id);
            opcion.textContent = respuesta.definicion;

            select.appendChild(opcion);
        });

        const feedback = document.createElement("div");

        feedback.style.cssText =
            "display:none;" +
            "margin-top:12px;" +
            "padding:12px 15px;" +
            "border-radius:7px;" +
            "font-size:14px;";

        feedback.setAttribute("aria-live", "polite");

        select.addEventListener("change", function () {
            if (!evaluado) {
                actualizarProgreso();
            }
        });

        tarjeta.appendChild(encabezado);
        tarjeta.appendChild(etiqueta);
        tarjeta.appendChild(select);
        tarjeta.appendChild(feedback);

        preguntas.appendChild(tarjeta);
    }

    // Iniciar o reiniciar actividad.
    function iniciarJuego() {
        preguntas.innerHTML = "";

        evaluado = false;

        respuestasAleatorias = mezclar(elementos);

        elementos.forEach(function (elemento, indice) {
            crearPregunta(elemento, indice);
        });

        puntuacion.textContent = "0 / 10";
        intentoTexto.textContent = intento;

        resultado.style.display = "none";

        botonComprobar.disabled = false;
        botonComprobar.style.opacity = "1";
        botonComprobar.style.cursor = "pointer";

        actualizarProgreso();
    }

    // Comprobar las respuestas.
    function comprobarRespuestas() {
        if (evaluado) {
            return;
        }

        const selects = preguntas.querySelectorAll("select");

        let completas = true;

        selects.forEach(function (select) {
            if (select.value === "") {
                completas = false;
            }
        });

        if (!completas) {
            resultado.style.display = "block";
            resultado.style.background = "#FFFBEB";
            resultado.style.borderColor = "#FDE68A";

            resultadoTitulo.textContent = "Actividad incompleta";
            resultadoNota.textContent = "Sin calificar";
            resultadoNota.style.color = "#92400E";

            resultadoMensaje.textContent =
                "Debes seleccionar una definición en las diez relaciones antes de comprobar tus respuestas.";

            return;
        }

        let correctas = 0;

        selects.forEach(function (select) {
            const seleccion = Number(select.value);
            const correcta = Number(select.dataset.correcta);

            const tarjeta = select.parentElement;
            const feedback = tarjeta.lastElementChild;

            const respuestaCorrecta = elementos.find(
                function (elemento) {
                    return elemento.id === correcta;
                }
            );

            if (seleccion === correcta) {
                correctas++;

                tarjeta.style.borderLeftColor = "#10B981";
                select.style.borderColor = "#10B981";

                feedback.style.display = "block";
                feedback.style.background = "#ECFDF5";
                feedback.style.color = "#047857";

                feedback.textContent = "✓ Respuesta correcta. +1 punto.";
            } else {
                tarjeta.style.borderLeftColor = "#EF4444";
                select.style.borderColor = "#EF4444";

                feedback.style.display = "block";
                feedback.style.background = "#FEF2F2";
                feedback.style.color = "#991B1B";

                feedback.textContent =
                    "✗ Respuesta incorrecta. Definición correcta: " +
                    respuestaCorrecta.definicion;
            }

            select.disabled = true;
        });

        evaluado = true;

        puntuacion.textContent = correctas + " / 10";

        botonComprobar.disabled = true;
        botonComprobar.style.opacity = "0.55";
        botonComprobar.style.cursor = "not-allowed";

        resultado.style.display = "block";
        resultadoNota.textContent = correctas + " / 10 puntos";

        if (correctas === 10) {
            resultado.style.background = "#ECFDF5";
            resultado.style.borderColor = "#A7F3D0";

            resultadoTitulo.textContent = "¡Excelente resultado!";
            resultadoNota.style.color = "#047857";

            resultadoMensaje.textContent =
                "Has relacionado correctamente los diez conceptos. " +
                "Demuestras un dominio completo de los contenidos evaluados.";

        } else if (correctas >= 7) {
            resultado.style.background = "#EFF6FF";
            resultado.style.borderColor = "#BFDBFE";

            resultadoTitulo.textContent = "¡Buen trabajo!";
            resultadoNota.style.color = "#1D4ED8";

            resultadoMensaje.textContent =
                "Has obtenido " + correctas +
                " respuestas correctas. Revisa las relaciones " +
                "incorrectas y realiza otro intento para alcanzar los diez puntos.";

        } else {
            resultado.style.background = "#FFFBEB";
            resultado.style.borderColor = "#FDE68A";

            resultadoTitulo.textContent = "Continúa practicando";
            resultadoNota.style.color = "#92400E";

            resultadoMensaje.textContent =
                "Has obtenido " + correctas +
                " respuestas correctas. Revisa las definiciones " +
                "y utiliza un nuevo intento para mejorar tu puntuación.";
        }

        resultado.scrollIntoView({
            behavior: "smooth",
            block: "nearest"
        });
    }

    // Eventos de los botones.
    botonComprobar.addEventListener(
        "click",
        comprobarRespuestas
    );

    botonReiniciar.addEventListener("click", function () {
        intento++;
        iniciarJuego();
    });

    // Primera ejecución.
    iniciarJuego();

})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}
